import { defineComponent, PropType } from 'vue';

import { OrientationValue } from '@game-studio/device';
import { CurrencyFormatter, IIntGameServerResponse, ServerSessionResponse, SessionDataStrings, SessionInitialData, SessionModel } from '../../../types';

// Spain must have GameId, TotalSpend, TotalProfit, GameName and SessionBalance

export type ComponentData = {
    sessionModel: SessionModel;
    gameNameLabel: HTMLElement;
    sessionBalanceLabel: HTMLElement;
    totalSpendLabel: HTMLElement;
    totalProfitLabel: HTMLElement;
};

const labelJustifications = {
    default: 'space-between',
    mid: 'space-around',
    centre: 'center'
} as const;

export default defineComponent({
    name: 'SessionDataVue',
    props: {
        onGameBegin: { type: Function, required: true },
        onGameComplete: { type: Function, required: true },
        labelJustification: { type: Object, default: () => ({ portrait: 'default', landscape: 'default' }) },
        formatCurrency: { type: Function as PropType<CurrencyFormatter>, required: true },
        strings: { type: Object as PropType<SessionDataStrings>, required: true },
        initialData: { type: Object as PropType<SessionInitialData>, required: true },
        displayName: { type: String, default: '' },
        isSubGame: { type: Boolean, required: true }
    },
    data(): ComponentData {
        return {
            sessionModel: {
                totalSpend: this.initialData.totalSpend,
                gameStart: { ...this.initialData.sessionData },
                gameEnd: { ...this.initialData.sessionData }
            },
            gameNameLabel: {} as HTMLElement,
            sessionBalanceLabel: {} as HTMLElement,
            totalSpendLabel: {} as HTMLElement,
            totalProfitLabel: {} as HTMLElement
        };
    },
    mounted(): void {
        const sessionDiv = document.getElementById('session-data');
        if (sessionDiv) {
            sessionDiv.style.justifyContent = labelJustifications[this.labelJustification['landscape'] as keyof typeof labelJustifications];
        } else {
            throw new Error('No element matching id session-data found');
        }

        const gameNameLabel = document.getElementById('game-name');
        if (gameNameLabel) {
            this.gameNameLabel = gameNameLabel;
        } else {
            throw new Error('No element matching id session-time found');
        }

        if (!this.isSubGame) {
            const sessionBalanceLabel = document.getElementById('session-balance');
            if (sessionBalanceLabel) {
                this.sessionBalanceLabel = sessionBalanceLabel;
            } else {
                throw new Error('No element matching id session-balance found');
            }

            const totalSpendLabel = document.getElementById('total-spend');
            if (totalSpendLabel) {
                this.totalSpendLabel = totalSpendLabel;
            } else {
                throw new Error('No element matching id session-balance found');
            }

            const totalProfitLabel = document.getElementById('total-profit');
            if (totalProfitLabel) {
                this.totalProfitLabel = totalProfitLabel;
            } else {
                throw new Error('No element matching id session-balance found');
            }
        }

        this.initialiseDisplay();

        this.onGameBegin(this.onDataResponse, this);
        this.onGameComplete(this.onGameEnd, this);
    },
    methods: {
        orientationChange(orientation: OrientationValue): void {
            const sessionDiv = document.getElementById('session-data');
            if (sessionDiv) {
                sessionDiv.style.justifyContent = labelJustifications[this.labelJustification[orientation] as keyof typeof labelJustifications];
            }
        },
        initialiseDisplay(): void {
            this.$emit('SessionDataOverlaysGame', true);
            this.updateGameNameDisplay(this.initialData.gameId);

            if (!this.isSubGame) {
                this.updateBalanceDisplay(this.initialData.sessionData.sessionBalance);
                this.updateTotalSpendDisplay(this.initialData.totalSpend);
                this.updateTotalProfitDisplay(this.initialData.sessionData.totalWin);
            }
        },
        onDataResponse(response: ServerSessionResponse): void {
            const esResponse = response as unknown as IIntGameServerResponse;
            // Resumes currently happen before this is mounted,
            // this future proofs incase that ever changes unintentionally
            if ((esResponse.RequestType === 'Resume')) { return; }
            if (esResponse.RequestType === 'CreateSession') {
                this.updateBalanceDisplay(0);
                this.updateTotalSpendDisplay(0);
                this.updateTotalProfitDisplay(0);
                return;
            }

            const jackpotWin = esResponse.JackpotResponse?.WinningDetails?.ImmediateWin ? esResponse.JackpotResponse?.WinningPot?.PrizeValue || 0 : 0;
            this.parseSessionData(esResponse);
            this.updateGameNameDisplay(esResponse.GameMessage?.GameId ?? 0);

            if (!this.isSubGame) {
                this.updateBalanceDisplay((this.sessionModel.gameStart.sessionBalance - this.sessionModel.gameEnd.sessionBalance) + this.sessionModel.gameEnd.totalWin - this.sessionModel.totalSpend + jackpotWin);
                this.updateTotalSpendDisplay(this.sessionModel.totalSpend);
            }
        },
        onGameEnd(): void {
            if (!this.isSubGame) {
                this.updateTotalProfitDisplay(this.sessionModel.gameEnd.totalWin);
                this.updateBalanceDisplay(this.sessionModel.gameEnd.totalWin - this.sessionModel.totalSpend);
            }
        },
        parseSessionData(data: IIntGameServerResponse): void {
            this.sessionModel = {
                totalSpend: data.SessionStatus.CurrentBet,
                gameStart: {
                    totalWin: data.SessionStatus.TotalWinnings,
                    sessionBalance: data.PlayerData.StartBalance
                },
                gameEnd: {
                    totalWin: data.SessionStatus.TotalWinnings,
                    sessionBalance: data.PlayerData.EndBalance
                }
            };
        },
        updateBalanceDisplay(val: number): void {
            this.sessionBalanceLabel.innerText = `${this.strings.balanceLabel}: ${this.formatBalance(val)}`;
        },
        updateGameNameDisplay(gameId: number = 0): void {
            this.gameNameLabel.innerText = `${this.displayName}: ` + gameId;
        },
        updateTotalSpendDisplay(val: number): void {
            this.totalSpendLabel.innerText = 'total apuestas: ' + this.formatBalance(val);
        },
        updateTotalProfitDisplay(val: number): void {
            this.totalProfitLabel.innerText = 'total ganancias: ' + this.formatBalance(val);
        },
        formatBalance(currencyValue: number): string {
            const balance: string = this.formatCurrency(Math.abs(currencyValue), true);
            const finalBalance = currencyValue < 0 ? `-${balance}` : balance;
            return finalBalance;
        }
    }
});